"use client";

import { useState } from "react";

type Status = "idle" | "loading" | "success" | "error";

const Newsletter = () => {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<Status>("idle");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;

    setStatus("loading");

    try {
      // TODO: wire up to the real newsletter provider / API route.
      await new Promise((resolve) => setTimeout(resolve, 500));
      setStatus("success");
    } catch {
      setStatus("error");
    }
  };

  return (
    <section className="hp-section hp-newsletter">
      <div className="hp-container">
        <div className="hp-newsletter-card hp-glass">
          <span className="hp-newsletter-icon" aria-hidden="true">
            ✉️
          </span>
          <div className="hp-section-label">Stay Updated</div>
          <h2 className="hp-section-title">Never Miss a New Guide</h2>
          <p className="hp-newsletter-sub">
            Get notified when Pinktra publishes new guides, ships a new product, or launches a
            major update. One email at a time, nothing else.
          </p>

          {status === "success" ? (
            <p className="hp-newsletter-success">You&apos;re in — thanks for subscribing.</p>
          ) : (
            <>
              <form className="hp-newsletter-form" onSubmit={handleSubmit}>
                <input
                  type="email"
                  required
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="hp-newsletter-input"
                  aria-label="Email address"
                  disabled={status === "loading"}
                />
                <button type="submit" className="hp-btn-primary" disabled={status === "loading"}>
                  {status === "loading" ? "Subscribing…" : "Subscribe"}
                </button>
              </form>
              <p className="hp-newsletter-note">
                {status === "error"
                  ? "Something went wrong — please try again."
                  : "No spam. Unsubscribe anytime."}
              </p>
            </>
          )}
        </div>
      </div>
    </section>
  );
};

export default Newsletter;
