"use client";

import { useEffect, useRef } from "react";

type RGB = { r: number; g: number; b: number };

type Ribbon = {
  strands: number;
  y0: number; // ribbon height at the left edge (fraction of hero height)
  y1: number; // …and at the right edge
  wave: number;
  width: number;
  twist: number;
  speed: number;
  phase: number;
  alpha: number;
  light: number; // 0 = pure accent, 1 = lighter tint
};

// Two silk ribbons that sweep diagonally across the whole hero in an S-curve,
// flowing side by side with different twists so they weave past each other.
const RIBBONS: Ribbon[] = [
  { strands: 38, y0: 0.82, y1: 0.24, wave: 0.07, width: 0.27, twist: 2.3, speed: 0.0003, phase: 0, alpha: 0.9, light: 0.35 },
  { strands: 28, y0: 0.94, y1: 0.4, wave: 0.06, width: 0.2, twist: 3.0, speed: -0.00024, phase: 2.4, alpha: 0.6, light: 0.65 },
];

const smooth = (u: number) => u * u * (3 - 2 * u);
const clamp01 = (n: number) => Math.min(Math.max(n, 0), 1);

/**
 * Silk-ribbon background for the Hero (self-running, no hover/touch).
 * - A twisting bundle of hairline strands with a glowing core, drawn only in
 *   the site's accent colour (plus a lighter tint of it) so it matches the theme.
 * - Two large ribbons sweep diagonally across the hero behind the content.
 *   They are hairline-thin and soften in the middle, so the text stays
 *   readable while the ribbons stay the star of the section.
 * - Looks exactly as designed; only the loop is hardened: it holds still
 *   while the page scrolls (keeps scrolling fluid), pauses off-screen /
 *   hidden tab, only coarsens its point spacing if frames run long, and
 *   shows a static frame for reduced-motion.
 */
const HeroBackground = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const section = canvas?.closest(".hp-hero") as HTMLElement | null;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !section || !ctx) return;

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const accent: RGB = { r: 138, g: 36, b: 53 };
    let isDark = false;
    const readTheme = () => {
      const root = document.documentElement;
      const parsed = parseColor(getComputedStyle(root).getPropertyValue("--accent-color").trim());
      if (parsed) Object.assign(accent, parsed);
      isDark = root.getAttribute("data-theme") === "dark";
    };
    readTheme();
    const themeObserver = new MutationObserver(() => {
      readTheme();
      if (reducedMotion) draw(3000);
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["data-theme"],
    });

    let width = 0;
    let height = 0;
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);

    const resize = () => {
      const rect = section.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      if (reducedMotion) draw(3000);
    };

    // Point spacing per quality level (0 = the original look). Only used to
    // coarsen slightly if the device can't keep up.
    const STEPS = [8, 10, 12];
    let quality = 0;
    let cy = new Float32Array(0);
    let wd = new Float32Array(0);
    let th = new Float32Array(0);

    const draw = (time: number) => {
      ctx.clearRect(0, 0, width, height);
      ctx.globalCompositeOperation = isDark ? "lighter" : "source-over";
      ctx.lineCap = "round";
      ctx.lineJoin = "round";

      const mobile = width < 640;
      const step = mobile ? 14 : STEPS[quality];
      const cols = Math.ceil((width + 20) / step) + 1;
      const strength = (isDark ? 1 : 0.8) * (mobile ? 0.6 : 1);
      const centreDip = mobile ? 0.2 : 0.25; // softer behind the text so it stays readable
      const lift = mix(accent, { r: 255, g: 255, b: 255 }, isDark ? 0.7 : 0.45);

      if (cy.length !== cols) {
        cy = new Float32Array(cols);
        wd = new Float32Array(cols);
        th = new Float32Array(cols);
      }

      for (const rb of RIBBONS) {
        const n = mobile ? Math.round(rb.strands * 0.6) : rb.strands;
        // Theme colours only: the accent itself, and a lighter tint of it.
        const left = accent;
        const right = accent;
        const centre = mix(accent, { r: 255, g: 255, b: 255 }, rb.light * (isDark ? 0.8 : 0.5));

        for (let i = 0; i < cols; i++) {
          const x = -10 + i * step;
          const u = clamp01(x / width);
          cy[i] =
            height * (rb.y0 + (rb.y1 - rb.y0) * smooth(u)) +
            Math.sin(u * Math.PI * 1.6 + rb.phase + time * 0.00025) * height * rb.wave;
          const envelope = 0.35 + 0.65 * Math.sin(u * Math.PI);
          wd[i] =
            height * rb.width * envelope * (0.7 + 0.3 * Math.sin(u * Math.PI * 1.7 + rb.phase * 1.3 + time * 0.0002));
          th[i] = u * Math.PI * rb.twist + time * rb.speed + rb.phase;
        }

        const core = new Path2D();
        const inner = new Path2D();
        const edge = new Path2D();
        for (let k = 0; k < n; k++) {
          const s = (k / (n - 1)) * 2 - 1;
          const as = Math.abs(s);
          const path = as < 0.34 ? core : as < 0.67 ? inner : edge;
          for (let i = 0; i < cols; i++) {
            const x = -10 + i * step;
            const y = cy[i] + s * wd[i] * Math.cos(th[i] + s * 0.3) + s * wd[i] * 0.12 * Math.sin(th[i] * 0.5);
            if (i === 0) path.moveTo(x, y);
            else path.lineTo(x, y);
          }
        }

        // Colour/opacity along the ribbon: full at the ends, softer in the middle.
        const base = ctx.createLinearGradient(0, 0, width, 0);
        base.addColorStop(0, rgba(left, 0));
        base.addColorStop(0.08, rgba(left, 1));
        base.addColorStop(0.3, rgba(left, 1));
        base.addColorStop(0.5, rgba(centre, centreDip));
        base.addColorStop(0.7, rgba(right, 1));
        base.addColorStop(0.92, rgba(right, 1));
        base.addColorStop(1, rgba(right, 0));
        ctx.strokeStyle = base;

        const A = rb.alpha * strength;
        ctx.lineWidth = 14;
        ctx.globalAlpha = A * 0.1; // wide bloom
        ctx.stroke(core);
        ctx.lineWidth = 4;
        ctx.globalAlpha = A * 0.18; // tight glow
        ctx.stroke(core);
        ctx.lineWidth = 1.6;
        ctx.globalAlpha = A;
        ctx.stroke(core);
        ctx.lineWidth = 1;
        ctx.globalAlpha = A * 0.7;
        ctx.stroke(inner);
        ctx.globalAlpha = A * 0.45;
        ctx.stroke(edge);

        // Travelling light streak; dimmed while it passes behind the text.
        const streak = (offset: number, alpha: number, target: Path2D) => {
          const p = ((time * 0.00011 + offset + rb.phase * 0.1) % 1.5) - 0.25;
          const sg = ctx.createLinearGradient(0, 0, width, 0);
          sg.addColorStop(0, rgba(lift, 0));
          sg.addColorStop(clamp01(p - 0.13), rgba(lift, 0));
          sg.addColorStop(clamp01(p), rgba(lift, 1));
          sg.addColorStop(clamp01(p + 0.13), rgba(lift, 0));
          sg.addColorStop(1, rgba(lift, 0));
          const dip = 1 - (1 - centreDip) * Math.exp(-(((p - 0.5) / 0.17) ** 2));
          ctx.strokeStyle = sg;
          ctx.lineWidth = 1.8;
          ctx.globalAlpha = alpha * strength * dip;
          ctx.stroke(target);
        };
        streak(0, 0.95, core);
        streak(0.18, 0.6, inner);
      }

      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = "source-over";
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(section);
    resize();

    if (reducedMotion) {
      draw(3000);
      return () => {
        resizeObserver.disconnect();
        themeObserver.disconnect();
      };
    }

    let frame = 0;
    let running = false;
    let visible = true;
    let lastTime = 0;
    let ema = 16;
    let counted = 0;
    let lastScroll = -1000;

    // While the page is scrolling, keep the last frame so scrolling stays fluid.
    const onScroll = () => {
      lastScroll = performance.now();
    };
    window.addEventListener("scroll", onScroll, { passive: true });

    const tick = (time: number) => {
      frame = requestAnimationFrame(tick);
      const dt = lastTime ? time - lastTime : 16;
      lastTime = time;
      if (time - lastScroll < 140) return;

      // If frames keep running long, coarsen the point spacing a little.
      ema = ema * 0.92 + Math.min(dt, 100) * 0.08;
      if (++counted >= 60) {
        counted = 0;
        if (ema > 26 && quality < STEPS.length - 1) {
          quality++;
          ema = 16;
        }
      }
      draw(time);
    };
    const start = () => {
      if (running || !visible || document.hidden) return;
      running = true;
      lastTime = 0;
      frame = requestAnimationFrame(tick);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(frame);
    };

    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) start();
      else stop();
    });
    io.observe(section);
    const onVisibility = () => (document.hidden ? stop() : start());
    document.addEventListener("visibilitychange", onVisibility);
    start();

    return () => {
      stop();
      io.disconnect();
      resizeObserver.disconnect();
      themeObserver.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("scroll", onScroll);
    };
  }, []);

  return (
    <div className="hp-hero-bg" aria-hidden="true">
      <canvas ref={canvasRef} className="hp-hero-bg-canvas" />
    </div>
  );
};

const rgba = (c: RGB, a: number) => `rgba(${c.r}, ${c.g}, ${c.b}, ${a})`;

function parseColor(value: string): RGB | null {
  if (!value) return null;
  const m = value.match(/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/i);
  if (m) return { r: +m[1], g: +m[2], b: +m[3] };
  const clean = value.replace("#", "").trim();
  const full = clean.length === 3 ? clean.split("").map((c) => c + c).join("") : clean;
  if (!/^[0-9a-fA-F]{6}$/.test(full)) return null;
  const n = parseInt(full, 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

function mix(a: RGB, b: RGB, t: number): RGB {
  return {
    r: Math.round(a.r + (b.r - a.r) * t),
    g: Math.round(a.g + (b.g - a.g) * t),
    b: Math.round(a.b + (b.b - a.b) * t),
  };
}

export default HeroBackground;