"use client";

import ArrowBackIosNewIcon from "@mui/icons-material/ArrowBackIosNew";
import ArrowForwardIosIcon from "@mui/icons-material/ArrowForwardIos";
import FormatQuoteIcon from "@mui/icons-material/FormatQuote";
import type { StaticImageData } from "next/image";
import Image from "next/image";
import { useCallback, useEffect, useState } from "react";

type Testimonial = {
  quote: string;
  name: string;
  role: string;
  image?: StaticImageData;
};

type Props = {
  testimonials: Testimonial[];
  /** Milliseconds between automatic slide changes. */
  intervalMs?: number;
};

const getInitials = (name: string) =>
  name
    .split(" ")
    .map((part) => part[0])
    .filter(Boolean)
    .slice(0, 2)
    .join("")
    .toUpperCase();

function Avatar({ name, image }: { name: string; image?: StaticImageData }) {
  const [failed, setFailed] = useState(false);

  return (
    <span className="hp-testi-avatar" aria-hidden="true">
      {image && !failed ? (
        <Image
          src={image}
          alt=""
          width={46}
          height={46}
          sizes="46px"
          placeholder="blur"
          className="hp-testi-avatar-img"
          onError={() => setFailed(true)}
        />
      ) : (
        getInitials(name)
      )}
    </span>
  );
}

export default function TestimonialsClient({ testimonials, intervalMs = 6000 }: Props) {
  const [index, setIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const total = testimonials.length;

  const goTo = useCallback(
    (next: number) => {
      setIndex(((next % total) + total) % total);
    },
    [total],
  );

  useEffect(() => {
    if (isPaused || total <= 1) return;

    const timer = setInterval(() => {
      setIndex((current) => (current + 1) % total);
    }, intervalMs);

    return () => clearInterval(timer);
  }, [isPaused, intervalMs, total]);

  return (
    <div
      className="hp-testi-spotlight"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onFocus={() => setIsPaused(true)}
      onBlur={() => setIsPaused(false)}
    >
      <FormatQuoteIcon className="hp-testi-quote-mark" aria-hidden="true" />

      {/* Every testimonial is rendered in the HTML; the track only slides. */}
      <div className="hp-testi-viewport">
        <div className="hp-testi-track" style={{ transform: `translateX(-${index * 100}%)` }}>
          {testimonials.map((t, i) => (
            <figure
              key={t.name}
              className="hp-testi-slide"
              aria-hidden={i !== index}
              aria-roledescription="slide"
              aria-label={`${i + 1} of ${total}`}
            >
              <blockquote className="hp-testi-text">
                <p>{t.quote}</p>
              </blockquote>

              <figcaption className="hp-testi-author">
                <Avatar name={t.name} image={t.image} />
                <div className="hp-testi-author-info">
                  <cite className="hp-testi-name">{t.name}</cite>
                  <span className="hp-testi-role">{t.role}</span>
                </div>
              </figcaption>
            </figure>
          ))}
        </div>
      </div>

      <div className="hp-testi-controls">
        <button
          type="button"
          className="hp-testi-arrow"
          onClick={() => goTo(index - 1)}
          aria-label="Previous testimonial"
        >
          <ArrowBackIosNewIcon aria-hidden="true" />
        </button>

        <div className="hp-testi-dots">
          {testimonials.map((t, i) => (
            <button
              key={t.name}
              type="button"
              className={`hp-testi-dot ${i === index ? "active" : ""}`}
              onClick={() => goTo(i)}
              aria-label={`Go to testimonial ${i + 1}`}
              aria-current={i === index}
            />
          ))}
        </div>

        <button
          type="button"
          className="hp-testi-arrow"
          onClick={() => goTo(index + 1)}
          aria-label="Next testimonial"
        >
          <ArrowForwardIosIcon aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}
