"use client";

import { useState } from "react";

type FAQItem = {
  q: string;
  a: string;
};

type Props = {
  faqs: FAQItem[];
};

export default function FAQClient({ faqs }: Props) {
  const [openFaq, setOpenFaq] = useState<number | null>(null);

  return (
    <div className="hp-faq-list">
      {faqs.map((faq, index) => {
        const isOpen = openFaq === index;
        const questionId = `faq-question-${index}`;
        const answerId = `faq-answer-${index}`;

        return (
          <div
            key={faq.q}
            className={`hp-faq-item hp-glass ${isOpen ? "open" : ""}`}
            role="button"
            tabIndex={0}
            aria-expanded={isOpen}
            aria-controls={answerId}
            onClick={() => setOpenFaq(isOpen ? null : index)}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                setOpenFaq(isOpen ? null : index);
              }
            }}
          >
            <div className="hp-faq-question" id={questionId}>
              <span>{faq.q}</span>
              <span className="hp-faq-icon" aria-hidden="true">
                {isOpen ? "−" : "+"}
              </span>
            </div>

            <div id={answerId} className="hp-faq-answer" role="region" aria-labelledby={questionId}>
              <p>{faq.a}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}
